void AxisTest(void){wchar_t name[100]=L"HeadRelay.Native32.";unsigned n=19;DWORD pid=GetCurrentProcessId();wchar_t digits[16];unsigned j=0;do{digits[j++]=L'0'+pid%10;pid/=10;}while(pid);while(j)name[n++]=digits[--j];name[n]=0;CHECK(SetEnvironmentVariableW(L"HEADRELAY_BRIDGE_HEAP",name),"test env");wchar_t mutex[120];lstrcpyW(mutex,name);lstrcatW(mutex,L"Mutex");HANDLE lock=CreateMutexW(0,FALSE,mutex),map=CreateFileMappingW(INVALID_HANDLE_VALUE,0,PAGE_READWRITE,0,108,name);CHECK(lock&&map,"isolated mapping");Shared *s=MapViewOfFile(map,FILE_MAP_ALL_ACCESS,0,0,108);CHECK(s,"mapping view");memset(s,0,108);HMODULE dll=LoadLibraryW(L"NPClient.dll");CHECK(dll,"load x86 DLL");Read read=(Read)GetProcAddress(dll,"NP_GetData");Reg reg=(Reg)GetProcAddress(dll,"NP_RegisterProgramProfileID");Control pause=(Control)GetProcAddress(dll,"NP_StopDataTransmission"),resume=(Control)GetProcAddress(dll,"NP_StartDataTransmission");Version version=(Version)GetProcAddress(dll,"NP_QueryVersion");FTRead ft=(FTRead)GetProcAddress(dll,"FTGetData");CHECK(read&&reg&&pause&&resume&&version&&ft,"undecorated stdcall exports");CHECK(GetProcAddress(dll,(LPCSTR)8)==(FARPROC)read,"ordinal 8");unsigned short v=0;CHECK(version(&v)==0&&v==0x500,"version ABI");reg(3450);CHECK(s->game==3450,"profile handshake");s->ack=3450;s->yaw=-3.14159265358979323846f/6;s->pitch=-3.14159265358979323846f/12;s->sequence=4;Pose p;CHECK(read(&p)==0&&p.status==0,"pose enabled");CHECK(p.yaw< -2730.4f&&p.yaw> -2730.6f,"yaw scale");CHECK(p.pitch< -1365.1f&&p.pitch> -1365.4f,"pitch scale");CHECK(p.checksum!=0,"packet checksum");s->yaw=0;s->pitch=0;CHECK(read(&p)==0&&p.status==0,"neutral enabled");pause();CHECK(read(&p)!=0&&p.status==1,"pause");resume();CHECK(read(&p)==0,"resume");unsigned char raw[92];CHECK(ft(raw)==1,"FreeTrack API");CHECK(((int32_t*)raw)[0]==4,"FreeTrack sequence");CHECK(read(0)!=0,"null pointer rejected");FreeLibrary(dll);UnmapViewOfFile(s);CloseHandle(map);CloseHandle(lock);print("PASS: native x86 ABI, exports, profile, pose, pause/resume, FreeTrack\r\n");ExitProcess(0);}